int rfcomm_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                   size_t size, int flags)
{
    struct sock *sk = sock->sk;
    int bytes_received;

    if (sk->sk_user_data && sk->sk_state == BT_CONNECTED) {
        /* Accept deferred RFCOMM connection setup if applicable */
        rfcomm_conn_accept_deferred(sk);
    }

    bytes_received = rfcomm_recvmsg_low_level(iocb, sock, msg, size, flags);

    if (bytes_received > 0) {
        sk->sk_rmem_alloc -= bytes_received;
        if (sk->sk_rmem_alloc < (sk->sk_rcvbuf / 2)) {
            rfcomm_unthrottle(sk);
        }
    }

    return bytes_received;
}

int rfcomm_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                   size_t size, int flags)
{
    int bytes_received;

    if (rfcomm_setup_deferred(sock))
        rfcomm_accept_connection(sock);

    bytes_received = rfcomm_low_level_recv(iocb, sock, msg, size, flags);

    if (bytes_received > 0)
        sock->sk->sk_forward_alloc -= bytes_received;

    if (sock->sk->sk_forward_alloc < RFCOMM_THROTTLE_THRESHOLD)
        rfcomm_unthrottle(sock);

    return bytes_received;
}

int rfcomm_recv_message(struct kiocb *iocb, struct socket *sock,
                        struct msghdr *msg, size_t size, int flags)
{
    int bytes_received;

    /* Check if RFCOMM connection setup is deferred and accept it if so */
    if (rfcomm_check_deferred_setup(sock)) {
        rfcomm_accept_setup(sock);
    }

    /* Call lower-level function to receive message */
    bytes_received = sock->ops->recvmsg(iocb, msg, size, flags);

    if (bytes_received > 0) {
        /* Update socket's receive memory allocation */
        sock_update_rmem_alloc(sock, bytes_received);

        /* Check if memory usage is below a certain threshold and unthrottle if needed */
        if (sock_rmem_usage_below_threshold(sock)) {
            rfcomm_unthrottle_connection(sock);
        }
    }

    return bytes_received;
}

int rfcomm_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    struct sock *sk = sock->sk;
    int len = 0;

    if (test_and_clear_bit(RFCOMM_DEFER_SETUP, &sk->sk_user_data))
        rfcomm_accept_connection(sk);

    len = sock->ops->recvmsg(iocb, sock, msg, size, flags);
    if (len > 0) {
        sk->sk_forward_alloc -= len;
        if (sk->sk_forward_alloc < (sk->sk_rcvbuf >> 1))
            rfcomm_unthrottle(sk);
    }

    return len;
}

#include <linux/socket.h>
#include <linux/ioctl.h>
#include <linux/skbuff.h>

int rfcomm_sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    int len = 0;
    struct sock *sk = sock->sk;

    if (test_bit(SK_SLEEP, &sk->sk_flags))
        return 0;

    if (sk->sk_state == TCP_LISTEN) {
        if (rfcomm_accept_deferred(sk) < 0)
            return -EAGAIN;
    }

    len = sock->ops->recvmsg(iocb, sock, msg, size, flags);
    if (len > 0)
        skb_free_datagram(sk, msg->msg_flags);

    if (sk->sk_rmem_alloc > (sk->sk_rcvbuf / 2))
        sk->sk_rmem_alloc = 0;

    if (sk->sk_rmem_alloc <= sk->sk_rcvbuf / 4)
        sock_unthrottle(sk);

    return len;
}
